-- Уникальность событий и версий, связи с hub/link/event, ненулевые результаты обязательных преобразований.
SELECT count(*) AS n FROM (SELECT event_id AS k FROM {{target:oil_dds__sat_daily_production}} GROUP BY event_id HAVING event_id IS NULL OR count(*)>1 UNION ALL SELECT production_hk AS k FROM {{target:oil_dds__sat_daily_production}} GROUP BY production_hk,entity_version HAVING production_hk IS NULL OR entity_version IS NULL OR count(*)>1 UNION ALL SELECT s.event_id AS k FROM {{target:oil_dds__sat_daily_production}} s LEFT JOIN {{target:oil_dds__hub_production_day}} h ON h.production_hk=s.production_hk LEFT JOIN {{target:oil_dds__link_production_day_well}} l ON l.link_hk=s.link_hk LEFT JOIN {{target:oil_dds__event}} e ON e.event_id=s.event_id WHERE h.production_hk IS NULL OR l.link_hk IS NULL OR l.production_hk IS DISTINCT FROM s.production_hk OR e.event_id IS NULL OR s.load_dts IS DISTINCT FROM e.load_dts OR s.record_source IS DISTINCT FROM e.record_source OR s.production_date IS NULL OR s.oil_tonnes IS NULL OR s.oil_tonnes<0 OR s.status IS NULL OR s.status NOT IN ('ACTIVE','INACTIVE')) q;
